from collections import Counter
import random

# English bigram frequencies (sample from Peter Norvig's bigram count)
# Simplified: we'll just count common bigrams.
COMMON_BIGRAMS = {'TH':1, 'HE':1, 'IN':1, 'ER':1, 'AN':1, 'ON':1, 'AT':1, 'EN':1, 'ES':1, 'ST':1, 'ED':1, 'IS':1, 'TO':1, 'IT':1, 'AR':1, 'TE':1, 'OF':1, 'AL':1, 'RE':1, 'NT':1}

def score(text):
    score = 0
    text = ''.join(c for c in text.upper() if c.isalpha())
    for i in range(len(text)-1):
        bigram = text[i:i+2]
        if bigram in COMMON_BIGRAMS:
            score += 1
    return score

def break_substitution(ciphertext):
    clean_ct = ''.join(c for c in ciphertext.upper() if c.isalpha() or c == ' ')
    ct_letters = [c for c in clean_ct if c.isalpha()]
    if not ct_letters:
        return ciphertext
    ct_freq = Counter(ct_letters)
    ranked_ct = [ch for ch, _ in ct_freq.most_common()]
    # Most frequent English letters
    english_freq = 'ETAOINSHRDLU'  # truncated
    initial_map = {}
    for i, ct_char in enumerate(ranked_ct):
        if i < len(english_freq):
            initial_map[ct_char] = english_freq[i]
        else:
            # Assign remaining letters to remaining English letters
            initial_map[ct_char] = chr(ord('A') + (i % 26))  # fallback
    # Hill climb
    best_map = dict(initial_map)
    best_score = score(apply_mapping(clean_ct, best_map))
    for _ in range(1000):
        map_copy = dict(best_map)
        # Swap two random ciphertext letters
        a, b = random.sample(list(map_copy.keys()), 2)
        map_copy[a], map_copy[b] = map_copy[b], map_copy[a]
        new_score = score(apply_mapping(clean_ct, map_copy))
        if new_score > best_score:
            best_score = new_score
            best_map = map_copy
    return apply_mapping(ciphertext.upper(), best_map)

def apply_mapping(text, mapping):
    result = []
    for ch in text:
        if ch.isalpha() and ch in mapping:
            result.append(mapping[ch])
        else:
            result.append(ch)
    return ''.join(result)
